private static boolean nextPermutation(int[] a) {
    int i = a.length-1;
    while(i>0 && a[i-1] >= a[i]) i--;
    if(i==0) return false;
    int j = a.length-1;
    while(a[j] <= a[i-1]) j--;
    int tmp = a[i-1]; a[i-1]=a[j]; a[j]=tmp;
    // reverse i..end
    int left=i, right=a.length-1;
    while(left<right) {
        tmp=a[left]; a[left]=a[right]; a[right]=tmp;
        left++; right--;
    }
    return true;
}

