public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    TreeMap<Character, Integer> freq = new TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.put(ch, freq.getOrDefault(ch, 0) + 1);
    }
    StringBuilder res = new StringBuilder();
    while (!freq.isEmpty()) {
        // ascending
        Iterator<Map.Entry<Character, Integer>> itAsc = freq.entrySet().iterator();
        while (itAsc.hasNext()) {
            Map.Entry<Character, Integer> entry = itAsc.next();
            char ch = entry.getKey();
            int cnt = entry.getValue();
            res.append(ch);
            cnt--;
            if (cnt == 0) {
                itAsc.remove();
            } else {
                entry.setValue(cnt);
            }
        }
        // descending
        Iterator<Map.Entry<Character, Integer>> itDesc = freq.descendingMap().entrySet().iterator();
        while (itDesc.hasNext()) {
            Map.Entry<Character, Integer> entry = itDesc.next();
            char ch = entry.getKey();
            int cnt = entry.getValue();
            res.append(ch);
            cnt--;
            if (cnt == 0) {
                itDesc.remove();
            } else {
                entry.setValue(cnt);
            }
        }
    }
    return res.toString();
}
