public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    String s = Integer.toString(n);
    int len = s.length();
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = s.charAt(i) - '0';
    }

    // Find the pivot: first index from right where digits[i] < digits[i+1]
    int pivot = len - 2;
    while (pivot >= 0 && digits[pivot] >= digits[pivot + 1]) {
        pivot--;
    }
    if (pivot < 0) {
        // Already the highest permutation
        return -1;
    }

    // Find rightmost successor to pivot
    int successor = len - 1;
    while (digits[successor] <= digits[pivot]) {
        successor--;
    }

    // Swap pivot and successor
    int temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Reverse the suffix
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }
    return (int) result;
}

